function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#e08a72");
  let grass = "#e08a72";
  fill(grass);
  brush.noStroke();
  brush.fill(grass, 30);
  brush.fillTexture(1, 30);
  let sky = "#e08a72";
  fill(sky);
  brush.fill(sky, 10);
  brush.fillTexture(0, 10);
  brush.beginShape(10);
  brush.vertex(0, 0);
  brush.vertex(200, 400);
  brush.vertex(400, 300);
  brush.vertex(400, 0);
  brush.endShape(true);
}

