function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");
  // painting goes here
  let y = height;
  for (let x = -100; x <= 100; x++) {
    fill("#296B49", "90%");
    ellipse(x, y, 80, 100);
    fill("#2B8156", "35%");
    ellipse(x, y - 250, 80, 100);
    fill("#878787");
    ellipse(x, y - 50, 80, 100);
    fill("#C8B132", "50%");
    ellipse(x + 30, y - 50, 80, 100);
    fill("#C89B52", "65%");
    ellipse(x + 60, y - 100, 80, 100);
    fill("#878787");
    ellipse(x + 90, y - 150, 80, 100);
    fill("#874D33", "30%");
    ellipse(x + 120, y - 200, 80, 100);
    fill("#2B5C3A", "80%");
    ellipse(x + 150, y - 250, 80, 100);
  }
}
