// prints "painting..." using text in p5.js
painting
  .push()

  // push state of the lights, no stroke
  brush.noStroke()

  // set color
  brush.fill('#ff6347')

  // paint for 400px
  for (let i = 0; i < 400; i++) {
    brush.fillBleed(0.6)
    brush.circle(i, 0, 50 + i)
    brush.fillBleed(0.5)
  }

  brush.fillTexture(0.5, 15)
  brush.fill('#5e5b4e', 0.2)

  // push state, no fill
  brush.noFill()
  for (let i = 0; i < 400; i++) {
    brush.fillBleed(0.4)
    brush.circle(i, 200, 300)
    brush.fillBleed(0.6)
  }

  // reset to initial color
  brush.fillBleed(0.5)
  brush.fill('#4a756a')

  // paint for 100px
  for (let i = 0; i < 100; i++) {
    brush.fill('#87c472')
    brush.vertex(i, 200)
  }
  brush.fillBleed(0.8)
  brush.vertex(0, 120)
  brush.endShape(true)

  // paint for 200px
  for (let i = 0; i < 200; i++) {
    brush.fill('#4e719f', 100)
    brush.vertex(i, 120)
  }
  brush.fillBleed(0.5)
  brush.vertex(400, 100)

  brush.fillTexture(0.8, 4)
  brush.fill('#1d4b3e', 100)
  brush.vertex(400, 100)

  brush.endShape(true)

  // paint for 200px
  for (let i = 0; i < 200; i++) {
    brush.fill('#4d845d', 100)
    brush.vertex(i, 40)
  }
  brush.fillBleed(0.8)
  brush.vertex(200, 40)

  // paint for 400px
  for (let i = 0; i < 400; i++) {
    brush.fill('#78c8c5')
    brush.circle(i, 40, 50)
    brush.fillBleed(0.4)
  }

  painting
    .pop()
