```javascript
import '@p5/brush';

let palette = ['orange', 'yellow', 'red', 'skyblue', 'green'];
let fillColor;
let texture;
let radius = 20;
let move;

function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  background("#f4efe4");
  translate(-width / 2, -height / 2);
  brush.noStroke();
  brush.background("skyblue");
  let colorIndex;
  for (let i = 0; i < palette.length; i++) {
    colorIndex = i % palette.length;
    fill(palette[colorIndex], 50);
    brush.brushOpt(palette[colorIndex], 80);
    radius += 5;
    let dirt = this.pokeDirt();
    if (dirt) {
      brush.brushOpt("green", 35);
      radius += 1;
      filler = this.pokeFiller();
      if (filler) {
        fill("orange", 60);
        brush.brushOpt("orange", 90);
        radius += 4;
      }
    }
    brush.brushOpt("red", 50);
    brush.fillTexture(0.8, 10);
  }
}

p5.Brush.prototype.pokeDirt = function() {
  return Math.random() < 0.4;
};

p5.Brush.prototype.pokeFiller = function() {
  return Math.random() < 0.3;
};
