text:
Create a full sky as the first layer with only fill in blend mode. Use fillTexture to bring in the hills as thin lines. Behind the sky, use the fill and draw the hills as thick rectangles.

```javascript
function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");
  fillTexture(50, 50);
  fill("#b0e1ff");
  brush.marks([
    { curvature: 0, vertex: [0, 0] },
    { curvature: 0, vertex: [400, 0] },
    { curvature: 0, vertex: [200, 300] },
  ]);
  drawBorders(
    [400, 150],
    [200, 200],
    [80, 200],
    [120, 200],
    [160, 200]
  );
}
function drawBorders(vertice, position, path) {
  stroke("#d0b383");
  for (var i = 0; i < path.length; i++) {
    strokeWidth(vertice[i].length * 10);
    push();
    translate(path[i][0], path[i][1]);
    stroke(i + 1);
    drawHills(path[i][0], vertice[i], i);
    pop();
  }
}

function drawHills(x, vertice, index) {
  push();
  fill("#4e8d48");
  stroke("#679658");
  vertex(x, 0);
  vertex(x + (vertice[index][0] - vertice[index - 1][0]) / 10, vertice[index - 1][1] * 0.8);
  vertex(x + (vertice[index][0] - vertice[index - 1][0]) / 10 * 1.5, vertice[index - 1][1] * 0.6);
  vertex(x + (vertice[index][0] - vertice[index - 1][0]) / 10 * 1.7, vertice[index - 1][1] * 0.6);
